ALTER TABLE public.organizations ADD COLUMN enabled_modules text[] NOT NULL DEFAULT ARRAY['hr','payroll','reports','attendance','leave','recruitment','field','security','billing','training','quickbooks','settings']::text[];
ALTER TABLE public.organizations ADD COLUMN demo_mode boolean NOT NULL DEFAULT false;
CREATE OR REPLACE FUNCTION public.validate_company_modules(_modules jsonb) RETURNS void LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF jsonb_typeof(_modules) IS DISTINCT FROM 'array' OR jsonb_array_length(_modules)>13 OR EXISTS(SELECT 1 FROM jsonb_array_elements(_modules) x WHERE jsonb_typeof(x)<>'string' OR (x#>>'{}') NOT IN ('hr','payroll','reports','attendance','leave','recruitment','field','security','billing','training','quickbooks','settings')) THEN RAISE EXCEPTION 'Invalid company features'; END IF; END $$;
CREATE OR REPLACE FUNCTION public.company_configuration() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT jsonb_build_object('modules',enabled_modules,'demo_mode',demo_mode) FROM public.organizations WHERE id=public.current_org_id() $$;
REVOKE ALL ON FUNCTION public.company_configuration() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.company_configuration() TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.has_workspace_access(_user_id uuid,_module text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.is_staff(_user_id) AND EXISTS(SELECT 1 FROM public.user_roles r JOIN public.organizations o ON o.id=r.org_id WHERE r.user_id=_user_id AND _module=ANY(o.enabled_modules) AND (r.role='admin' OR (_module IN ('hr','payroll','reports','attendance','leave','recruitment','field','security','billing','training','quickbooks','settings') AND (r.role='manager' OR _module IN ('attendance','field','security','training')) AND CASE WHEN EXISTS(SELECT 1 FROM public.user_workspace_access a WHERE a.user_id=_user_id) THEN EXISTS(SELECT 1 FROM public.user_workspace_access a WHERE a.user_id=_user_id AND _module=ANY(a.modules)) ELSE true END))) $$;
DO $$ DECLARE d text; BEGIN
SELECT pg_get_functiondef(oid) INTO d FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='validate_company_setup';
d:=replace(d,'FOR k IN SELECT jsonb_object_keys(_details) LOOP','IF _details ? ''modules'' THEN PERFORM public.validate_company_modules(_details->''modules''); END IF; FOR k IN SELECT jsonb_object_keys(_details) WHERE jsonb_object_keys<>''modules'' LOOP'); EXECUTE d;
SELECT pg_get_functiondef(oid) INTO d FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='complete_company_setup';
d:=replace(d,'UPDATE public.profiles SET org_id=company','UPDATE public.organizations SET enabled_modules=ARRAY(SELECT jsonb_array_elements_text(coalesce(_details->''modules'',''["hr","payroll","reports","settings"]''::jsonb))) WHERE id=company; UPDATE public.profiles SET org_id=company'); EXECUTE d;
SELECT pg_get_functiondef(oid) INTO d FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='issue_company_setup';
d:=replace(d,'INSERT INTO public.company_setup_invitations(org_id,email','IF company IS NOT NULL THEN UPDATE public.organizations SET enabled_modules=ARRAY(SELECT jsonb_array_elements_text(coalesce(_details->''modules'',''["hr","payroll","reports","settings"]''::jsonb))) WHERE id=company; END IF; INSERT INTO public.company_setup_invitations(org_id,email'); EXECUTE d;
SELECT pg_get_functiondef(oid) INTO d FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='update_platform_company';
d:=replace(d,'UPDATE public.organizations SET name=trim(_details->>''company_name'') WHERE id=_org;', 'UPDATE public.organizations SET name=trim(_details->>''company_name''),enabled_modules=CASE WHEN _details ? ''modules'' THEN ARRAY(SELECT jsonb_array_elements_text(_details->''modules'')) ELSE enabled_modules END WHERE id=_org;'); EXECUTE d;
SELECT pg_get_functiondef(oid) INTO d FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='platform_companies'; d:=replace(d,'FROM public.organizations o ORDER BY', 'FROM public.organizations o ORDER BY'); d:=replace(d,'''{}''::jsonb) FROM public.organizations o', '''{}''::jsonb)||jsonb_build_object(''modules'',o.enabled_modules) FROM public.organizations o'); EXECUTE d;
END $$;